<template><view class="page"><view class="hero"><text class="eyebrow">专家服务</text><text class="title">让专业命名师再精批一遍</text><text class="subtitle">查看认证专家套餐、精批订单，也可以申请专家入驻。</text></view><text class="section-title">专家套餐</text><view v-if="loading" class="loading">正在读取专家服务…</view><view v-else-if="!packages.length" class="empty card"><text class="empty-title">专家套餐正在准备中</text><text>你可以先提交专家入驻申请。</text></view><view v-for="item in packages" :key="item.id" class="card"><view class="row between"><text class="card-title">{{item.expert_name}}</text><text>{{Number(item.expert_rating||0).toFixed(1)}} ★</text></view><text class="package">{{item.name}}</text><text class="muted">{{item.description}}</text><view class="row between meta"><text>{{item.delivery_days}} 天 · {{item.revision_count}} 次修改</text><text class="price">¥{{Number(item.price).toFixed(2)}}</text></view></view><text class="section-title">专家入驻</text><view v-if="profile" class="card"><text :class="['badge',profile.status==='approved'?'completed':profile.status==='rejected'?'failed':'']">{{profile.status==='approved'?'已认证':profile.status==='rejected'?'未通过':'审核中'}}</text><text class="card-title profile-title">{{profile.display_name}} · {{profile.title}}</text><text class="muted">{{profile.bio}}</text></view><view v-else class="card"><input class="input" v-model="form.display_name" placeholder="专家展示名"/><input class="input" v-model="form.title" placeholder="专业头衔"/><input class="input" v-model="form.specialties" placeholder="擅长领域"/><input class="input" v-model.number="form.experience_years" type="number" placeholder="从业年限"/><textarea class="input textarea" v-model="form.bio" placeholder="专业经历与服务理念（至少20字）"/><button class="primary" @click="apply">提交入驻申请</button></view><text class="section-title">我的精批订单</text><view v-if="!orders.length" class="empty card"><text>暂无精批订单</text></view><view v-for="item in orders" :key="item.id" class="card"><view class="row between"><text class="card-title">{{item.package_name}}</text><text class="badge">{{orderStatus[item.status]||item.status}}</text></view><text class="muted">{{item.expert_name}} · {{item.order_no}}</text></view></view></template>
<script setup>import{reactive,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api,requireLogin}from'../../api';const packages=ref([]),profile=ref(null),orders=ref([]),loading=ref(true),form=reactive({display_name:'',title:'',specialties:'',experience_years:0,bio:'',portfolio:''}),orderStatus={submitted:'待接单',accepted:'服务中',delivered:'已交付',completed:'已完成'};async function load(){if(!requireLogin())return;loading.value=true;try{[packages.value,profile.value,orders.value]=await Promise.all([api.expertPackages(),api.expertProfile(),api.expertOrders()])}catch(e){uni.showToast({title:e.message,icon:'none'})}finally{loading.value=false}}async function apply(){if(form.bio.length<20)return uni.showToast({title:'专业经历至少20字',icon:'none'});try{profile.value=await api.applyExpert({...form,experience_years:Number(form.experience_years)});uni.showToast({title:'申请已提交',icon:'success'})}catch(e){uni.showToast({title:e.message,icon:'none'})}}onShow(load)</script>
<style scoped>.package{display:block;font-size:34rpx;font-weight:700;margin:25rpx 0 10rpx}.meta{margin-top:24rpx;color:#7d746b;font-size:23rpx}.price{color:#a94439;font-size:34rpx;font-weight:700}.profile-title{display:block;margin:22rpx 0 12rpx}</style>
